-- FaceReel's first PostgreSQL schema. SQLite data is intentionally not used at runtime.
CREATE TYPE "ProjectStatus" AS ENUM ('DRAFT','READY','RENDERING','COMPLETED','FAILED','CANCELLED');
CREATE TYPE "UploadStatus" AS ENUM ('PENDING','UPLOADED','FAILED');
CREATE TYPE "ValidationStatus" AS ENUM ('PENDING','VALID','VALID_WITH_WARNINGS','INVALID');
CREATE TYPE "RenderJobStatus" AS ENUM ('QUEUED','PROCESSING','COMPLETED','FAILED','CANCELLED');
CREATE TYPE "DispatchStatus" AS ENUM ('PENDING','SENT');
CREATE TYPE "AssetType" AS ENUM ('MASTER_VIDEO','POSTER_FRAME');
CREATE TYPE "EmailKind" AS ENUM ('PROCESSING','COMPLETION','FAILURE');
CREATE TYPE "EmailStatus" AS ENUM ('PENDING','SENDING','SENT','FAILED');

CREATE TABLE "FaceReelProject" ("id" TEXT PRIMARY KEY,"ownerTokenHash" TEXT NOT NULL,"email" TEXT NOT NULL,"name" TEXT NOT NULL,"instagramUsername" TEXT NOT NULL,"status" "ProjectStatus" NOT NULL DEFAULT 'DRAFT',"outputFormat" TEXT NOT NULL DEFAULT 'mp4',"orientation" TEXT NOT NULL DEFAULT 'portrait',"aspectRatio" TEXT NOT NULL DEFAULT '9:16',"resolution" TEXT NOT NULL DEFAULT '1080x1920',"frameRate" INTEGER NOT NULL DEFAULT 30,"secondsPerImage" DOUBLE PRECISION NOT NULL DEFAULT .12,"transitionType" TEXT NOT NULL DEFAULT 'cut',"transitionDuration" DOUBLE PRECISION NOT NULL DEFAULT 0,"backgroundColor" TEXT NOT NULL DEFAULT '#000000',"musicObjectKey" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "SourceImage" ("id" TEXT PRIMARY KEY,"projectId" TEXT NOT NULL,"orderIndex" INTEGER NOT NULL,"r2Bucket" TEXT NOT NULL,"r2ObjectKey" TEXT NOT NULL,"originalFilename" TEXT NOT NULL,"contentType" TEXT NOT NULL,"sizeBytes" BIGINT NOT NULL,"width" INTEGER,"height" INTEGER,"orientation" INTEGER,"checksum" TEXT,"uploadStatus" "UploadStatus" NOT NULL DEFAULT 'PENDING',"validationStatus" "ValidationStatus" NOT NULL DEFAULT 'PENDING',"validationError" TEXT,"detectionMetadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "RenderJob" ("id" TEXT PRIMARY KEY,"projectId" TEXT NOT NULL,"email" TEXT NOT NULL,"status" "RenderJobStatus" NOT NULL DEFAULT 'QUEUED',"progress" INTEGER NOT NULL DEFAULT 0,"stage" TEXT NOT NULL DEFAULT 'QUEUED',"progressDetail" JSONB,"attemptCount" INTEGER NOT NULL DEFAULT 0,"maxAttempts" INTEGER NOT NULL DEFAULT 3,"workerRevision" TEXT,"errorCode" TEXT,"errorMessage" TEXT,"internalError" TEXT,"processingStartedAt" TIMESTAMP(3),"heartbeatAt" TIMESTAMP(3),"completedAt" TIMESTAMP(3),"failedAt" TIMESTAMP(3),"cancelledAt" TIMESTAMP(3),"completionEmailSentAt" TIMESTAMP(3),"failureEmailSentAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "RenderedAsset" ("id" TEXT PRIMARY KEY,"renderJobId" TEXT NOT NULL,"projectId" TEXT NOT NULL,"assetType" "AssetType" NOT NULL,"variant" TEXT NOT NULL,"r2Bucket" TEXT NOT NULL,"r2ObjectKey" TEXT NOT NULL,"contentType" TEXT NOT NULL,"sizeBytes" BIGINT NOT NULL,"width" INTEGER,"height" INTEGER,"durationMs" INTEGER,"frameRate" DOUBLE PRECISION,"checksum" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "RenderJobEvent" ("id" BIGSERIAL PRIMARY KEY,"renderJobId" TEXT NOT NULL,"eventType" TEXT NOT NULL,"stage" TEXT,"progress" INTEGER,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "RenderDispatch" ("id" TEXT PRIMARY KEY,"renderJobId" TEXT NOT NULL,"status" "DispatchStatus" NOT NULL DEFAULT 'PENDING',"attemptCount" INTEGER NOT NULL DEFAULT 0,"taskName" TEXT,"lastError" TEXT,"nextAttemptAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"sentAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "EmailDelivery" ("id" TEXT PRIMARY KEY,"renderJobId" TEXT NOT NULL,"kind" "EmailKind" NOT NULL,"status" "EmailStatus" NOT NULL DEFAULT 'PENDING',"attemptCount" INTEGER NOT NULL DEFAULT 0,"providerMessageId" TEXT,"lastError" TEXT,"sentAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
ALTER TABLE "FaceReelProject" ADD COLUMN "ownerAccessToken" TEXT NOT NULL;
ALTER TABLE "SourceImage" ADD CONSTRAINT "SourceImage_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "FaceReelProject"("id") ON DELETE CASCADE;
ALTER TABLE "RenderJob" ADD CONSTRAINT "RenderJob_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "FaceReelProject"("id") ON DELETE CASCADE;
ALTER TABLE "RenderedAsset" ADD CONSTRAINT "RenderedAsset_renderJobId_fkey" FOREIGN KEY ("renderJobId") REFERENCES "RenderJob"("id") ON DELETE CASCADE;
ALTER TABLE "RenderedAsset" ADD CONSTRAINT "RenderedAsset_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "FaceReelProject"("id") ON DELETE CASCADE;
ALTER TABLE "RenderJobEvent" ADD CONSTRAINT "RenderJobEvent_renderJobId_fkey" FOREIGN KEY ("renderJobId") REFERENCES "RenderJob"("id") ON DELETE CASCADE;
ALTER TABLE "RenderDispatch" ADD CONSTRAINT "RenderDispatch_renderJobId_fkey" FOREIGN KEY ("renderJobId") REFERENCES "RenderJob"("id") ON DELETE CASCADE;
ALTER TABLE "EmailDelivery" ADD CONSTRAINT "EmailDelivery_renderJobId_fkey" FOREIGN KEY ("renderJobId") REFERENCES "RenderJob"("id") ON DELETE CASCADE;
CREATE UNIQUE INDEX "SourceImage_r2ObjectKey_key" ON "SourceImage"("r2ObjectKey"); CREATE UNIQUE INDEX "SourceImage_projectId_orderIndex_key" ON "SourceImage"("projectId","orderIndex");
CREATE INDEX "RenderJob_status_createdAt_idx" ON "RenderJob"("status","createdAt"); CREATE INDEX "RenderJob_status_heartbeatAt_idx" ON "RenderJob"("status","heartbeatAt");
CREATE UNIQUE INDEX "RenderedAsset_r2ObjectKey_key" ON "RenderedAsset"("r2ObjectKey"); CREATE UNIQUE INDEX "RenderedAsset_renderJobId_assetType_variant_key" ON "RenderedAsset"("renderJobId","assetType","variant");
CREATE UNIQUE INDEX "RenderDispatch_renderJobId_key" ON "RenderDispatch"("renderJobId"); CREATE UNIQUE INDEX "EmailDelivery_renderJobId_kind_key" ON "EmailDelivery"("renderJobId","kind");
CREATE UNIQUE INDEX "FaceReelProject_ownerAccessToken_key" ON "FaceReelProject"("ownerAccessToken");
